function isTileAnimationFinished() {
	if (tiles.length === 0) return true;
	return tiles.every(tile => tile.frameTimer >= tile.expandEndFrame);
}

function addTile() {
	tiles = [];
	let swappedColor = bgColor;
	bgColor = shapeColor;
	shapeColor = swappedColor;

	if (checkerParity === 0) {
		checkerParity = 1;
	} else {
		checkerParity = 0;
	}
	for (let i = 0; i < gridRes; i++) {
		for (let j = 0; j < gridRes; j++) {
			let x = i * cellSize + cellSize / 2;
			let y = j * cellSize + cellSize / 2;
			let d = dist(x, y, width / 2, height / 2);
			let t = -int(map(d, 0, sqrt(2) * width / 2, 50, 0));
			if ((i + j) % 2 === checkerParity) {
				tiles.push(new Tile(x, y, cellSize, shapeColor, t));
			}
		}
	}
}


function easeInOutQuad(x) {
	return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
}

/*------------------------------------------------------------------------------------------*/

class Tile {
	constructor(x, y, w, colorHex, t) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.maxW = w;
		this.minW = w * 0.4;
		this.frameTimer = t;
		this.shrinkEndFrame = 50;
		this.expandStartFrame = this.shrinkEndFrame + 30;
		this.expandEndFrame = this.expandStartFrame + 50;
		this.baseColor = color(colorHex);
		this.corner = 0;
		this.targetColor = color(random(palette));
		this.currentColor = this.baseColor;
		this.angle = 0;
	}

	display() {
		push();
		translate(this.x, this.y);
		rotate(this.angle);
		fill(this.currentColor);
		noStroke();
		square(0, 0, this.w, this.corner);
		pop();
	}

	update() {
		this.frameTimer++;
		let shrinkProgress = this.getPhaseProgress(0, this.shrinkEndFrame);
		if (shrinkProgress !== null) {
			this.w = lerp(this.maxW, this.minW, shrinkProgress);
			this.corner = lerp(0, this.minW, shrinkProgress);
			this.currentColor = lerpColor(this.baseColor, this.targetColor, shrinkProgress);
			this.angle = lerp(0, PI / 2, shrinkProgress);
		}

		let expandProgress = this.getPhaseProgress(this.expandStartFrame, this.expandEndFrame);
		if (expandProgress !== null) {
			this.w = lerp(this.minW, this.maxW, expandProgress);
			this.corner = lerp(this.minW, 0, expandProgress);
			this.currentColor = lerpColor(this.targetColor, this.baseColor, expandProgress);
			this.angle = lerp(0, PI / 2, expandProgress);
		}
	}

	getPhaseProgress(start, end) {
		if (!(start < this.frameTimer && this.frameTimer < end)) return null;
		let progress = norm(this.frameTimer, start, end - 1);
		return easeInOutQuad(progress);
	}

	run() {
		this.display();
		this.update();
	}
}

